test('validate error handling and status codes', async ({ request }) => {
// 404 Not Found
const notFoundResponse = await request.get(
`${BACKEND_CONFIG.BASE_URL}${BACKEND_CONFIG.ENDPOINTS.users.get.replace(':id', '99999')}`
