expect(notFoundResponse.status()).toBe(404);
// 400 Bad Request
const badRequestResponse = await request.post(
`${BACKEND_CONFIG.BASE_URL}${BACKEND_CONFIG.ENDPOINTS.users.create}`,
{
data: { name: '' }, // Missing required fields
}
);
