// Enable parallel execution
fullyParallel: true,
// Number of parallel workers (default: number of CPU cores)
workers: process.env.CI ? 4 : undefined,
// Timeout for entire test
timeout: 30 * 1000,
// Timeout for each expect assertion
expect: { timeout: 5000 },
});
